import { installState, navState } from '$lib/store.svelte';
// @ts-expect-error — generated by Wails
import { LogInfo } from '@wails/runtime/runtime.js';
import { PAGE_IDS, PAGES_NEEDING_VALIDATION } from '$lib/types';
import type { ManualLayout, PageID } from '$lib/types';
import { t } from '$lib/i18n';
// @ts-expect-error — generated by Wails
import { SetCurrentPage, ValidateUserAccount, SaveUserAccount, ValidateDiskSelection, SaveDiskSelection, ValidateManualLayout, SaveManualLayout, RebootAndClose } from '@wails/go/gui/App.js';
// @ts-expect-error — generated by Wails
import { gui } from '@wails/go/models';

// Tracks whether user has confirmed installation (prevents dialog re-show)
let _installationConfirmed = false;

// Page-specific error message keys for validation failures. Translated at use
// time (not at module load) so switching language updates the fallbacks too.
const PAGE_ERROR_KEYS: Record<PageID, string> = {
	[PAGE_IDS.WELCOME]: 'validation.selectLanguage',
	[PAGE_IDS.USER_ACCOUNT]: 'validation.selectUserAccount',
	[PAGE_IDS.DISK_SELECTION]: 'validation.selectDisk',
	[PAGE_IDS.CONFIRMATION]: 'validation.reviewInstallation',
	[PAGE_IDS.INSTALLATION]: 'validation.waitInstallation',
	[PAGE_IDS.FINISH]: 'validation.installationComplete',
};

function pageErrorMessage(page: PageID): string {
	const key = PAGE_ERROR_KEYS[page];
	return key ? t(key) : 'Please fix the issues above to continue.';
}

/**
 * Result of a Next attempt. `error` carries a frontend validation failure;
 * `backendError` carries a failure reported by the Go backend bindings. Both
 * are surfaced through the same validation modal in App.svelte.
 */
export interface GoNextResult {
	error: string | null;
	backendError: string | null;
}

export async function goNext(currentPage: number): Promise<GoNextResult> {
	// Show confirmation dialog on Confirmation page (only once)
	if (currentPage === PAGE_IDS.CONFIRMATION && !_installationConfirmed) {
		installState.showConfirmDialog = true;
		return { error: null, backendError: null }; // Don't advance yet
	}
	_installationConfirmed = false; // Reset for next time

	// Validate current page if needed
	if (PAGES_NEEDING_VALIDATION.has(currentPage as PageID)) {
		const validationError = await validateCurrentPage(currentPage);
		if (validationError) return { error: null, backendError: validationError };
	}

	// Commit (save) page data after validation passes, then move the backend to
	// the next page. Both are Wails calls that can reject (I/O, serialization,
	// a backend invariant); surface that through the same modal instead of
	// letting an unhandled rejection swallow the click.
	try {
		await commitPageData(currentPage);

		const nextPage = currentPage + 1;
		await SetCurrentPage(new gui.PageID({ Value: nextPage }));

		navState.direction = 'forward';
		navState.currentPage = nextPage;
	} catch (err) {
		return { error: null, backendError: errorMessage(err) };
	}

	return { error: null, backendError: null }; // Success
}

export async function goBack(currentPage: number): Promise<string | null> {
	// Update backend
	const prevPage = currentPage - 1;
	try {
		await SetCurrentPage(new gui.PageID({ Value: prevPage }));
	} catch (err) {
		return errorMessage(err);
	}

	navState.direction = 'backward';
	navState.currentPage = prevPage;

	return null; // Success
}

function errorMessage(err: unknown): string {
	return err instanceof Error ? err.message : String(err);
}

// Called when user clicks "Yes" in confirmation dialog
export function confirmInstallation(): void {
	_installationConfirmed = true;
}

// Called when user cancels/closes the confirmation dialog
export function cancelInstallation(): void {
	_installationConfirmed = false;
}

export async function finish(): Promise<{ error: string | null }> {
	try {
		await RebootAndClose();
		return { error: null };
	} catch (err) {
		return { error: err instanceof Error ? err.message : 'Failed to reboot' };
	}
}

async function validateCurrentPage(page: number): Promise<string | null> {
	try {
		if (page === PAGE_IDS.USER_ACCOUNT) {
			await ValidateUserAccount({
				username: installState.username,
				password: installState.password,
				confirmPassword: installState.confirmPassword,
			});
		}

		if (page === PAGE_IDS.DISK_SELECTION) {
			await ValidateDiskSelection({
				diskId: installState.diskId,
				size: installState.disk?.size ?? 0,
				fileSystem: installState.fileSystem,
			});

			// Manual (dualboot) mode: the layout itself must have one Boot + one Root.
			if (installState.manualMode && installState.manualLayout) {
				await ValidateManualLayout(installState.manualLayout);
			}
		}

		return null; // Validation passed
	} catch (err) {
		// Manual (dualboot) mode: surface the backend's specific reason (e.g.
		// "exactly one ESP partition is required", partition sizes exceed the disk)
		// instead of a generic prompt about assigning roles.
		if (page === PAGE_IDS.DISK_SELECTION && installState.manualMode) {
			if (installState.manualLayout) {
				const p = installState.manualLayout.partitions.map(
					(x) => `${x.path || '<new>'}:${x.sizeMB}MB type='${x.type || 'none'}'`,
				).join(', ');
				LogInfo(
					`[NEXT] manual layout: diskMB=${installState.manualLayout.diskSizeMB} diskBytes=${installState.manualLayout.diskSizeBytes} freeMB=${installState.manualLayout.freeMB} freeSectors=${installState.manualLayout.freeSectors} parts=[${p}]`,
				);
			}
			return err instanceof Error ? err.message : t('validation.selectDiskManual');
		}
		return pageErrorMessage(page as PageID);
	}
}

// CommitPageData validates AND saves page data. Called after validation passes.
async function commitPageData(page: number): Promise<void> {
	if (page === PAGE_IDS.USER_ACCOUNT) {
		await SaveUserAccount({
			username: installState.username,
			password: installState.password,
			confirmPassword: installState.confirmPassword,
		});
	}

	if (page === PAGE_IDS.DISK_SELECTION) {
		await SaveDiskSelection({
			diskId: installState.diskId,
			size: installState.disk?.size ?? 0,
			fileSystem: installState.fileSystem,
		});

		// Manual (dualboot) mode: persist the designed layout so the installer
		// only formats the Boot/Root partitions.
		if (installState.manualMode && installState.manualLayout) {
			await SaveManualLayout(installState.manualLayout as ManualLayout);
		}
	}
}
